def fizz_buzz(n: int) -> None:
    """
    Prints the FizzBuzz sequence up to n.

    For each number from 1 to n inclusive:
    - Prints "FizzBuzz" if divisible by both 3 and 5,
    - "Fizz" if divisible by 3,
    - "Buzz" if divisible by 5,
    - The number itself otherwise.

    Args:
        n: The upper limit of the sequence.
    """
    for number in range(1, n + 1):
        if number % 3 == 0 and number % 5 == 0:
            print("FizzBuzz")
        elif number % 3 == 0:
            print("Fizz")
        elif number % 5 == 0:
            print("Buzz")
        else:
            print(number)

def check_key(d, key):
    if key in d:
        return True
    for value in d.values():
        if isinstance(value, dict):
            if check_key(value, key):
                return True
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict) and check_key(item, key):
                    return True
    return False

def capitalize_first_and_fourth(s: str) -> str:
    """
    Capitalize the first and fourth characters of a string, lowercase the rest.

    Args:
        s: The input string.

    Returns:
        The modified string.
    """
    result = []
    for idx, char in enumerate(s):
        if idx == 0 or idx == 3:
            result.append(char.upper())
        else:
            result.append(char.lower())
    return ''.join(result)

def max_subarray_sum(numbers, k):
    # Calculate sum of the first window of size k
    current_sum = sum(numbers[:k])
    max_sum = current_sum

    # Slide the window and update sums
    for i in range(k, len(numbers)):
        current_sum = current_sum - numbers[i - k] + numbers[i]
        if current_sum > max_sum:
            max_sum = current_sum

    return max_sum

def decimal_to_binary(n: int) -> str:
    if n == 0:
        return '0'
    elif n == 1:
        return '1'
    else:
        return decimal_to_binary(n // 2) + str(n % 2)

from typing import List

def permute(s: str) -> List[str]:
    """Return all permutations of the input string."""
    if len(s) == 1:
        return [s]
    result: List[str] = []
    for i in range(len(s)):
        current_char = s[i]
        remaining_chars = s[:i] + s[i+1:]
        for p in permute(remaining_chars):
            result.append(current_char + p)
    return result

from typing import Optional, List

def nth_highest(marks: List[int], n: int) -> Optional[int]:
    if n <= 0 or n > len(marks):
        return None
    sorted_marks = sorted(marks, reverse=True)
    return sorted_marks[n - 1]

def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def celsius_to_fahrenheit(celsius):
    # Convert Celsius to Fahrenheit
    return (celsius * 9/5) + 32

def fahrenheit_to_celsius(fahrenheit):
    # Convert Fahrenheit to Celsius
    return (fahrenheit - 32) * 5/9

