def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_prime(n):
    # Numbers less than 2 are not prime
    if n < 2:
        return False
    # 2 is the only even prime
    if n == 2:
        return True
    # Even numbers greater than 2 are not prime
    if n % 2 == 0:
        return False
    # Check odd divisors from 3 up to sqrt(n)
    max_divisor = int(n ** 0.5) + 1
    for i in range(3, max_divisor, 2):
        if n % i == 0:
            return False
    return True

from typing import Dict, Any

def flatten_dict(nested_dict: Dict[str, Any]) -> Dict[str, Any]:
    """
    Flatten a nested dictionary into a single-level dictionary.

    Args:
        nested_dict: A dictionary that may contain nested dictionaries.

    Returns:
        A flattened dictionary where keys from nested levels are prefixed.

    Raises:
        TypeError: If the input is not a dictionary.
    """
    if not isinstance(nested_dict, dict):
        raise TypeError("Input must be a dictionary")

    flat_dict: Dict[str, Any] = {}

    def _flatten_helper(current_dict: Dict[str, Any], prefix: str = "") -> None:
        for key, value in current_dict.items():
            new_key = f"{prefix}{key}" if prefix else key
            if isinstance(value, dict):
                _flatten_helper(value, new_key + ".")
            else:
                flat_dict[new_key] = value

    _flatten_helper(nested_dict)
    return flat_dict

def product_of_list(numbers):
    # Start with 1 because multiplying by 1 doesn't change the product
    result = 1
    for num in numbers:
        result *= num
    return result

def count_primes(numbers):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    return sum(1 for num in numbers if is_prime(num))

def is_palindrome(s):
    cleaned = ''.join(c.lower() for c in s if c.isalpha())
    return cleaned == cleaned[::-1]

def generate_strings(n):
    # Base case: empty string when n=0
    if n == 0:
        return ['']
    # Recursive step: for each letter, append all valid strings of length n-1
    result = []
    for c in 'abcdefghijklmnopqrstuvwxyz':
        for s in generate_strings(n - 1):
            if not s or s[-1] != c:  # Ensure no consecutive repeats
                result.append(c + s)
    return result

